@extends('admin.layout') @section('content')<h1>Cerrar caja #{{ $shift->id }}</h1><p class="muted">Revisa los totales y registra el arqueo.</p>@include('admin.summary')<div class="panel" style="max-width:560px"><form method="post" data-once data-confirm="?Confirmas el cierre de esta caja?">@csrf<input type="hidden" name="operation_id" value="{{ old('operation_id', $operation) }}"><label>Efectivo contado (Bs)<input id="counted" name="counted" inputmode="decimal" value="{{ old('counted') }}" required pattern="[0-9]+([.][0-9]{1,2})?"></label><p>Diferencia: <strong id="difference">?</strong></p><label>Observaci?n<textarea id="note" name="note" maxlength="2000">{{ old('note') }}</textarea></label><p class="muted">La observaci?n es obligatoria si existe diferencia.</p><button type="submit">Confirmar cierre</button></form></div><script>const counted=document.getElementById('counted'),note=document.getElementById('note'),difference=document.getElementById('difference'),expected={{ $shift->opening_cents + $summary['cash_sales_cents'] + ($summary['cash_inflows_cents'] ?? 0) - ($summary['cash_outflows_cents'] ?? 0) }};function update(){let v=counted.value;if(!/^\d+(\.\d{1,2})?$/.test(v)){difference.textContent='?';note.required=false;return}let p=v.split('.'),c=Number(p[0])*100+Number((p[1]||'').padEnd(2,'0')),d=c-expected;difference.textContent=(d<0?'-':'')+'Bs '+(Math.abs(d)/100).toFixed(2);note.required=d!==0}counted.addEventListener('input',update);update();</script>@endsection